import "server-only";
import { db } from "@/lib/db";
import {
  decryptToken,
  encryptToken,
  tokenKeyring,
  tokenUsesActiveKey,
} from "@/lib/crypto";
import { z } from "zod";

// One owner page includes its retained deletion job. Jobs outlive User, so use
// the union of owner IDs. Dry-run executes SELECTs and crypto only, no locks/writes.
export async function rotateTokenPage(
  options: { apply?: boolean; after?: string; take?: number } = {},
) {
  tokenKeyring();
  const after = options.after ? z.uuid().parse(options.after) : "";
  const take = Math.min(100, Math.max(1, options.take ?? 50));
  const owners = await db.$queryRaw<
    { id: string }[]
  >`SELECT id FROM (SELECT id FROM "User" WHERE "encryptedRefreshToken" IS NOT NULL UNION SELECT "userId" AS id FROM "AccountDeletionJob" WHERE "encryptedRevocationToken" IS NOT NULL AND "credentialExpiresAt">clock_timestamp()) owners WHERE id>${after} ORDER BY id LIMIT ${take}`;
  const counts = {
    scanned: 0,
    current: 0,
    eligible: 0,
    updated: 0,
    conflicts: 0,
    failed: 0,
  };
  for (const { id: ownerId } of owners) {
    const user = await db.user.findUnique({
      where: { id: ownerId },
      select: { encryptedRefreshToken: true, deletionRequestedAt: true },
    });
    const job = await db.accountDeletionJob.findUnique({
      where: { userId: ownerId },
      select: {
        id: true,
        encryptedRevocationToken: true,
        credentialExpiresAt: true,
      },
    });
    for (const kind of ["user", "job"] as const) {
      const value =
        kind === "user"
          ? user?.encryptedRefreshToken
          : job?.encryptedRevocationToken;
      if (!value || (kind === "job" && job!.credentialExpiresAt <= new Date()))
        continue;
      counts.scanned++;
      try {
        // Validate even current envelopes, including removed or misconfigured keys.
        const plaintext = decryptToken(value, ownerId);
        if (tokenUsesActiveKey(value)) {
          counts.current++;
          continue;
        }
        counts.eligible++;
        if (!options.apply) continue;
        const encrypted = encryptToken(plaintext, ownerId);
        const result =
          kind === "user"
            ? await db.user.updateMany({
                where: {
                  id: ownerId,
                  encryptedRefreshToken: value,
                  deletionRequestedAt: null,
                },
                data: { encryptedRefreshToken: encrypted },
              })
            : await db.accountDeletionJob.updateMany({
                where: {
                  userId: ownerId,
                  id: job!.id,
                  encryptedRevocationToken: value,
                  credentialExpiresAt: { gt: new Date() },
                  credentialErasedAt: null,
                },
                data: { encryptedRevocationToken: encrypted },
              });
        if (result.count) counts.updated++;
        else counts.conflicts++;
      } catch {
        counts.failed++;
      }
    }
  }
  return {
    ...counts,
    cursor: owners.length === take ? owners.at(-1)!.id : null,
  };
}
